    0x2939f74b2d9b43B9A29bF3333eE213DE175919A4
);

_oracleRelayerCParams[HAIVELO] = IOracleRelayer.OracleRelayerCollateralParams({
    oracle: delayedOracle[HAIVELO],
    safetyCRatio: 2.2e27, // 220%
    liquidationCRatio: 2e27 // 200%
