// Encoded Params: 0x0000000000000000000000002939f74b2d9b43b9a29bf3333ee213de175919a40000000000000000000000000000000000000000071bcc1ef9311a1f98000000000000000000000000000000000000000000000006765c793fa10079d0000000

oracleRelayer.initializeCollateralType(HAIVELO, abi.encode(_oracleRelayerCParams[HAIVELO]));
